package com.fream.back.domain.m45.service.command;

import com.fream.back.domain.m52.entity.Xrv73;
import com.fream.back.domain.m52.entity.Xbp24Type;
import com.fream.back.domain.m52.service.command.Xbp24CommandService;
import com.fream.back.domain.m99.entity.Xhq12;
import com.fream.back.domain.m99.entity.Xtw92;
import com.fream.back.domain.m99.entity.Xhq12Status;
import com.fream.back.domain.m99.service.query.Xtw92QueryService;
import com.fream.back.domain.m85.entity.Xkh73Status;
import com.fream.back.domain.m85.entity.Xpj42;
import com.fream.back.domain.m85.entity.Xzt63;
import com.fream.back.domain.m85.entity.Xpj42Status;
import com.fream.back.domain.m85.service.query.Xzt63QueryService;
import com.fream.back.domain.m45.entity.Xfr60;
import com.fream.back.domain.m45.entity.Xzn53Status;
import com.fream.back.domain.m45.exception.Xzn53ErrorCode;
import com.fream.back.domain.m45.exception.Xzn53Exception;
import com.fream.back.domain.m45.repository.Xfr60Repository;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m63.service.command.Xms75CommandService;
import com.fream.back.global.utils.Xwg86;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;




@Slf4j
@Service
@RequiredArgsConstructor
public class Xfr60CommandService {

    private final Xfr60Repository orderShipmentRepository;
    private final Xbp24CommandService notificationCommandService;
    private final Xzt63QueryService saleBidQueryService;
    private final Xtw92QueryService orderBidQueryService;
    private final Xms75CommandService warehouseStorageCommandService;
    private final Xwg86 cjTrackingPlaywright;











    @Transactional
    public Xfr60 createOrderShipment(Xhq12 order, String receiverName, String receiverPhone,
                                             String postalCode, String address) {
        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
                order.getId(), receiverName);

        Xfr60 shipment = Xfr60.builder()
                .order(order)
                .receiverName(receiverName)
                .receiverPhone(receiverPhone)
                .postalCode(postalCode)
                .address(address)
                .status(Xzn53Status.PENDING)
                .build();

        Xfr60 savedShipment = orderShipmentRepository.save(shipment);
        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
                savedShipment.getId(), order.getId());

        return savedShipment;
    }







    @Transactional
    public void updateShipmentStatus(Xfr60 shipment, Xzn53Status newStatus) {
        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
                shipment.getId(), shipment.getStatus(), newStatus);

        try {
            shipment.updateStatus(newStatus);
            orderShipmentRepository.save(shipment);

            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
                    shipment.getId(), newStatus);
        } catch (IllegalStateException e) {
            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                    shipment.getId(), e.getMessage(), e);

            throw new Xzn53Exception(
                    Xzn53ErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
                    e
            );
        }
    }






    @Transactional
    public void updateSaleStatusToSold(Long orderId) {
        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);


        Xzt63 saleBid = saleBidQueryService.findByOrderId(orderId);
        if (saleBid != null) {
            Xpj42 sale = saleBid.getSale();
            if (sale != null && sale.getStatus().canTransitionTo(Xpj42Status.SOLD)) {
                log.info("Xpj42 상태 'SOLD'로 변경: saleId={}, sellerId={}",
                        sale.getId(), sale.getSeller().getId());

                sale.updateStatus(Xpj42Status.SOLD);


                if (sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }


                Xjm45 seller = sale.getSeller();
                notificationCommandService.createNotification(
                        seller.getId(),
                        Xrv73.SHOPPING,
                        Xbp24Type.BID,
                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                );

                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                        seller.getId(), sale.getId());
            } else {
                log.debug("Xpj42 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
            }
        } else {
            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
        }


        try {
            Xtw92 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));

            if (orderBid != null) {
                Xpj42 sale = orderBid.getSale();
                if (sale != null && sale.getStatus().canTransitionTo(Xpj42Status.SOLD)) {
                    log.info("Xtw92 기반 Xpj42 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
                            orderBid.getId(), sale.getId());

                    sale.updateStatus(Xpj42Status.SOLD);


                    Xjm45 seller = sale.getSeller();
                    notificationCommandService.createNotification(
                            seller.getId(),
                            Xrv73.SHOPPING,
                            Xbp24Type.BID,
                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                    );

                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                            seller.getId(), sale.getId());
                } else {
                    log.debug("Xpj42 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
                }
            }
        } catch (IllegalArgumentException e) {
            log.warn("Xtw92 조회 실패: orderId={}, error={}", orderId, e.getMessage());

        }

        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
    }






    @Transactional
    public void completeOrder(Long orderId) {
        log.info("주문 완료 처리 시작: orderId={}", orderId);

        try {

            Xtw92 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));

            Xhq12 order = orderBid.getOrder();
            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
                    order.getId(), order.getUser().getId(), order.getStatus());


            order.updateStatus(Xhq12Status.COMPLETED);
            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);


            updateSaleStatusToSold(orderId);


            Xjm45 buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    Xrv73.SHOPPING,
                    Xbp24Type.BID,
                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());

        } catch (Exception e) {
            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
            throw new Xzn53Exception(
                    Xzn53ErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }








    @Transactional
    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new Xzn53Exception(Xzn53ErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {
            Xfr60 shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new Xzn53Exception(
                            Xzn53ErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));


            shipment.updateTrackingInfo(courier, trackingNumber);


            Xhq12 order = shipment.getOrder();
            order.updateStatus(Xhq12Status.IN_TRANSIT);

            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());


            Xjm45 buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    Xrv73.SHOPPING,
                    Xbp24Type.BID,
                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());


            updateSaleStatusToSold(order.getId());


            Xzt63 saleBid = saleBidQueryService.findByOrderId(order.getId());
            if (saleBid != null) {
                Xpj42 sale = saleBid.getSale();
                if (sale != null && sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }
            }


            updateOrderAndSaleBidStatusToCompleted(order.getId());

            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);

        } catch (Xzn53Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
            throw new Xzn53Exception(
                    Xzn53ErrorCode.SHIPMENT_NOT_FOUND,
                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }




    @Transactional
    public void updateShipmentStatuses() {
        log.info("전체 배송 상태 업데이트 시작");


        List<Xfr60> shipments = orderShipmentRepository.findByStatusIn(
                List.of(Xzn53Status.IN_TRANSIT, Xzn53Status.OUT_FOR_DELIVERY)
        );

        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());

        int successCount = 0;
        int errorCount = 0;

        for (Xfr60 shipment : shipments) {
            try {
                String trackingNumber = shipment.getTrackingNumber();
                if (trackingNumber == null || trackingNumber.isBlank()) {
                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
                    errorCount++;
                    continue;
                }

                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
                        shipment.getId(), trackingNumber);


                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
                Xzn53Status newStatus = mapToShipmentStatus(currentStatus);

                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
                        shipment.getId(), currentStatus, newStatus);


                if (shipment.getStatus() == newStatus) {
